/* ═══════════ БЕЙДЖ-ТАЙМЕР ═══════════ */
.badge-timer {
  display: inline-block;
  background: rgba(243,156,18,.25);
  color: var(--xp, #f39c12);
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 800;
  margin-left: 6px;
  font-variant-numeric: tabular-nums;
}
.badge-timer.ready { background: var(--success); color: #fff; }

/* ═══════════ КАЗИНО — новый вид ═══════════ */
.casino-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin-bottom: 14px;
}
.casino-tab {
  padding: 14px 6px;
  background: var(--bg-2);
  border: 2px solid transparent;
  border-radius: 12px;
  text-align: center;
  cursor: pointer;
  transition: all .2s;
  color: var(--text);
  font-size: 11px;
  font-weight: 700;
}
.casino-tab.active {
  border-color: var(--money);
  background: rgba(243,156,18,.15);
  box-shadow: 0 0 16px rgba(243,156,18,.3);
}
.casino-tab-emoji { font-size: 28px; display: block; margin-bottom: 4px; }

.casino-stage {
  background: linear-gradient(160deg, #1a0f2e, #2c1810, #1a0f2e);
  border-radius: 20px;
  padding: 30px 20px;
  min-height: 240px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
  position: relative;
  overflow: hidden;
  border: 2px solid rgba(243,156,18,.2);
}
.casino-stage::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, rgba(243,156,18,.15), transparent 60%);
  pointer-events: none;
}
.casino-display {
  font-size: 96px;
  line-height: 1;
  text-align: center;
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 4px 20px rgba(243,156,18,.5));
}

/* Анимации */
@keyframes spin-slow { to { transform: rotate(1080deg); } }
.casino-display.spinning-coin { animation: spin-slow 1.5s cubic-bezier(.4,0,.6,1); }
.casino-display.spinning-wheel { animation: spin-slow 2s cubic-bezier(.4,0,.6,1); }

@keyframes dice-roll {
  0% { transform: rotate(0deg) scale(1); }
  25% { transform: rotate(180deg) scale(1.2) translateY(-30px); }
  50% { transform: rotate(360deg) scale(1) translateY(0); }
  75% { transform: rotate(540deg) scale(1.2) translateY(-20px); }
  100% { transform: rotate(720deg) scale(1) translateY(0); }
}
.casino-display.rolling-dice { animation: dice-roll 1.2s ease-out; }

@keyframes slot-spin { 0%{transform:translateY(0)} 100%{transform:translateY(-300px)} }
.casino-slots { display: flex; gap: 12px; justify-content: center; }
.slot-reel {
  width: 70px; height: 90px;
  background: var(--bg-2);
  border: 3px solid var(--money);
  border-radius: 12px;
  font-size: 50px;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
  position: relative;
}
.slot-reel.spinning .reel-inner { animation: slot-spin .15s linear infinite; }
.reel-inner { display: flex; flex-direction: column; }

@keyframes jackpot-pulse {
  0%,100% { transform: scale(1); }
  50% { transform: scale(1.15); filter: drop-shadow(0 0 30px gold); }
}
.casino-display.jackpot-win { animation: jackpot-pulse 0.6s infinite; }

/* Результат казино */
.casino-result {
  padding: 16px;
  border-radius: 14px;
  text-align: center;
  margin-top: 14px;
  font-weight: 700;
  animation: fadeIn .3s;
}
.casino-result.win {
  background: linear-gradient(135deg, rgba(46,204,113,.3), rgba(39,174,96,.2));
  border: 2px solid var(--success);
  color: var(--success);
}
.casino-result.lose {
  background: linear-gradient(135deg, rgba(231,76,60,.3), rgba(192,57,43,.2));
  border: 2px solid var(--danger);
  color: var(--danger);
}

/* ═══════════ КЕЙСЫ — 3 карточки, модалка ═══════════ */
.case-list-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}
.case-preview-card {
  background: linear-gradient(135deg, #2c1810, #4a2818, #2c1810);
  border-radius: 18px;
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  cursor: pointer;
  border: 2px solid rgba(243,156,18,.3);
  transition: all .2s;
  position: relative;
  overflow: hidden;
}
.case-preview-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(circle at 20% 50%, rgba(243,156,18,.15), transparent 50%);
  pointer-events: none;
}
.case-preview-card:active {
  transform: scale(.97);
  border-color: var(--money);
}
.case-preview-emoji { font-size: 56px; flex-shrink: 0; position: relative; z-index: 1; }
.case-preview-info { flex: 1; min-width: 0; position: relative; z-index: 1; }
.case-preview-name { font-size: 18px; font-weight: 800; }
.case-preview-sub { font-size: 12px; color: var(--hint); margin-top: 4px; }
.case-preview-price {
  font-size: 22px;
  font-weight: 900;
  color: var(--money);
  text-shadow: 0 2px 8px rgba(243,156,18,.6);
}

/* Превью в модалке кейса */
.case-modal-items {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  margin-bottom: 16px;
}
.case-modal-item {
  background: var(--bg-3);
  border-radius: 14px;
  padding: 12px 10px;
  text-align: center;
  border: 2px solid transparent;
  position: relative;
}
.case-modal-item-svg {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 140px;
  background: radial-gradient(circle at center, rgba(243,156,18,.1), transparent 70%);
  border-radius: 10px;
  margin-bottom: 8px;
}
.case-modal-item-name {
  font-size: 12px;
  font-weight: 800;
  margin-bottom: 4px;
  min-height: 32px;
}
.case-modal-item-chance {
  font-size: 14px;
  font-weight: 900;
  color: var(--money);
  background: rgba(243,156,18,.15);
  border-radius: 8px;
  padding: 3px 8px;
  display: inline-block;
  margin-bottom: 6px;
}
.case-modal-item-stats {
  font-size: 11px;
  color: var(--hint);
  font-weight: 700;
  line-height: 1.3;
}

.cases-grid { display: grid; grid-template-columns: 1fr; gap: 12px; }
